import { useState } from 'react'

import { ErrorMessage } from '../../../shared/ui/ErrorMessage/ErrorMessage'
import { filterTodos, type TodoFilter } from '../../application/TodoFilter'
import { AddTodoForm } from '../AddTodoForm/AddTodoForm'
import { TodoFilterBar } from '../TodoFilterBar/TodoFilterBar'
import { TodoItem } from '../TodoItem/TodoItem'
import { useTodos } from '../useTodos/useTodos'

export const TodoList = () => {
  const { state, addTodo } = useTodos()
  const [filter, setFilter] = useState<TodoFilter>('all')

  if (state.status === 'loading') return <p>Loading todos…</p>
  if (state.status === 'failed') return <ErrorMessage>The todos could not be loaded.</ErrorMessage>

  const visible = filterTodos(state.todos, filter)

  return (
    <>
      <TodoFilterBar value={filter} onChange={setFilter} />
      <AddTodoForm onAdd={addTodo} />
      {visible.length > 0 ? (
        <ul aria-label="Todos">
          {visible.map((todo) => (
            <TodoItem key={todo.id} todo={todo} />
          ))}
        </ul>
      ) : (
        <p>{state.todos.length > 0 ? 'No todos match this filter.' : 'No todos yet.'}</p>
      )}
    </>
  )
}
